// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // The reference implementation always returns a non-zero owner after deployment,
        // because the initializer sets msg.sender as the owner and the Ownable logic
        // prevents transferring ownership to address(0). The buggy version returns address(0)
        // independently of the stored owner, so it will return address(0) even when
        // a valid owner exists.
        address retrievedOwner = c.owner();
        assertTrue(retrievedOwner != address(0));
    }
}

